typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);

static void matvec(int n, const int* restrict indptr, const int* restrict indices,
                   const double* restrict data, const double* restrict x, double* restrict y)
{
    int i = 0;
    /* process 4 rows at once for ILP; each row sum keeps sequential order */
    for (; i + 4 <= n; i += 4) {
        int a0 = indptr[i], e0 = indptr[i+1];
        int a1 = e0,        e1 = indptr[i+2];
        int a2 = e1,        e2 = indptr[i+3];
        int a3 = e2,        e3 = indptr[i+4];
        double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
        int l0 = e0 - a0, l1 = e1 - a1, l2 = e2 - a2, l3 = e3 - a3;
        int m = l0; if (l1 < m) m = l1; if (l2 < m) m = l2; if (l3 < m) m = l3;
        for (int t = 0; t < m; t++) {
            s0 += data[a0+t] * x[indices[a0+t]];
            s1 += data[a1+t] * x[indices[a1+t]];
            s2 += data[a2+t] * x[indices[a2+t]];
            s3 += data[a3+t] * x[indices[a3+t]];
        }
        for (int t = a0 + m; t < e0; t++) s0 += data[t] * x[indices[t]];
        for (int t = a1 + m; t < e1; t++) s1 += data[t] * x[indices[t]];
        for (int t = a2 + m; t < e2; t++) s2 += data[t] * x[indices[t]];
        for (int t = a3 + m; t < e3; t++) s3 += data[t] * x[indices[t]];
        y[i] = s0; y[i+1] = s1; y[i+2] = s2; y[i+3] = s3;
    }
    for (; i < n; i++) {
        double s = 0.0;
        for (int t = indptr[i]; t < indptr[i+1]; t++) s += data[t] * x[indices[t]];
        y[i] = s;
    }
}

int run_loop(void* fptr, char* st, double* resid, double* v, int* ipntr,
             double* workd, double* workl, int n,
             const int* indptr, const int* indices, const double* data, long* count)
{
    naupd_t f = (naupd_t)fptr;
    long c = 0;
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        int ido = *(int*)(st + 0x34);
        if (ido == 1 || ido == 5) {
            matvec(n, indptr, indices, data, workd + ipntr[0], workd + ipntr[1]);
            c++;
        } else {
            *count = c;
            return ido;
        }
    }
}
