{"command": "cat > arpack_loop.c <<'EOF'
#include <immintrin.h>
#include <stdlib.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);

/* Blocked ELL layout: rows permuted (sorted by length), groups of 4 rows.
   For group g, entries t=0..len_g-1 stored interleaved: val[off_g + 4*t + lane], idx likewise.
   Padding: val=0, idx=0. Each lane sums its own row strictly sequentially (identical to CSR order),
   so results are bitwise identical to scalar CSR matvec (adding +-0 leaves sum unchanged). */
typedef struct { int ngroups; const int* goff; const int* glen; const int* rows; const double* val; const int* idx; } ell_t;

__attribute__((target("avx2")))
static void matvec_ell(const ell_t* E, const double* restrict x, double* restrict y)
{
    for (int g = 0; g < E->ngroups; g++) {
        const double* v = E->val + E->goff[g];
        const int* ix = E->idx + E->goff[g];
        int L = E->glen[g];
        __m256d s = _mm256_setzero_pd();
        for (int t = 0; t < L; t++) {
            __m128i id = _mm_loadu_si128((const __m128i*)(ix + 4*t));
            __m256d xv = _mm256_i32gather_pd(x, id, 8);
            __m256d av = _mm256_loadu_pd(v + 4*t);
            s = _mm256_add_pd(s, _mm256_mul_pd(av, xv));
        }
        double out[4];
        _mm256_storeu_pd(out, s);
        const int* r = E->rows + 4*g;
        for (int l = 0; l < 4; l++) if (r[l] >= 0) y[r[l]] = out[l];
    }
}

static void matvec_csr(int n, const int* restrict indptr, const int* restrict indices,
                       const double* restrict data, const double* restrict x, double* restrict y)
{
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        for (int t = indptr[i]; t < indptr[i+1]; t++) s += data[t] * x[indices[t]];
        y[i] = s;
    }
}

void matvec_csr_export(int n, const int* indptr, const int* indices, const double* data,
                       const double* x, double* y) { matvec_csr(n, indptr, indices, data, x, y); }
void matvec_ell_export(int ngroups, const int* goff, const int* glen, const int* rows,
                       const double* val, const int* idx, const double* x, double* y) {
    ell_t E = {ngroups, goff, glen, rows, val, idx}; matvec_ell(&E, x, y); }

int has_avx2(void) { return __builtin_cpu_supports("avx2"); }

int run_loop(void* fptr, char* st, double* resid, double* v, int* ipntr,
             double* workd, double* workl, int n,
             const int* indptr, const int* indices, const double* data,
             int ngroups, const int* goff, const int* glen, const int* rows,
             const double* val, const int* idx, int use_ell, long* count)
{
    naupd_t f = (naupd_t)fptr;
    ell_t E = {ngroups, goff, glen, rows, val, idx};
    long c = 0;
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
        int ido = *(int*)(st + 0x34);
        if (ido == 1 || ido == 5) {
            if (use_ell) matvec_ell(&E, workd + ipntr[0], workd + ipntr[1]);
            else matvec_csr(n, indptr, indices, data, workd + ipntr[0], workd + ipntr[1]);
            c++;
        } else {
            *count = c;
            return ido;
        }
    }
}
