    }
    civ[0] = -wi * d1; civ[1] = 0.0; civ[2] = 0.0; civ[3] = -wi * d2;
    double cmax = 0.0; int icmax = 0;
    for (int j = 1; j <= 4; j++) if (fabs(crv[j-1]) + fabs(civ[j-1]) > cmax) { cmax = fabs(crv[j-1]) + fabs(civ[j-1]); icmax = j; }
    if (cmax < smini) {
        double bnorm = dmax(fabs(b(1,1)) + fabs(b(1,2)), fabs(b(2,1)) + fabs(b(2,2)));
        if (smini < 1.0 && bnorm > 1.0) { if (bnorm > bignum * smini) *scale = 1.0 / bnorm; }
