        *xnorm = temp * bnorm; *info = 1; return;
    }
    const int* pv = ipivot[icmax-1];
    double ur11 = crv[icmax-1], ui11 = civ[icmax-1];
    double cr21 = crv[pv[1]-1], ci21 = civ[pv[1]-1], ur12 = crv[pv[2]-1], ui12 = civ[pv[2]-1];
    double cr22 = crv[pv[3]-1], ci22 = civ[pv[3]-1];
    double ur11r, ui11r, lr21, li21, ur12s, ui12s, ur22, ui22;
    if (icmax == 1 || icmax == 4) {
        if (fabs(ur11) > fabs(ui11)) { double temp = ui11 / ur11; ur11r = 1.0 / (ur11 * (1.0 + temp*temp)); ui11r = -temp * ur11r; }
        else { double temp = ur11 / ui11; ui11r = -1.0 / (ui11 * (1.0 + temp*temp)); ur11r = -temp * ui11r; }
        lr21 = cr21 * ur11r; li21 = cr21 * ui11r; ur12s = ur12 * ur11r; ui12s = ur12 * ui11r;
        ur22 = cr22 - ur12 * lr21; ui22 = ci22 - ur12 * li21;
    } else {
        ur11r = 1.0 / ur11; ui11r = 0.0; lr21 = cr21 * ur11r; li21 = ci21 * ur11r;
        ur12s = ur12 * ur11r; ui12s = ui12 * ur11r;
        ur22 = cr22 - ur12 * lr21 + ui12 * li21; ui22 = -ur12 * li21 - ui12 * lr21;
    }
    double u22abs = fabs(ur22) + fabs(ui22);
    if (u22abs < smini) { ur22 = smini; ui22 = 0.0; *info = 1; }
    double br1, br2, bi1, bi2;
    if (rswap[icmax-1]) { br2 = b(1,1); br1 = b(2,1); bi2 = b(1,2); bi1 = b(2,2); }
    else { br1 = b(1,1); br2 = b(2,1); bi1 = b(1,2); bi2 = b(2,2); }
    br2 = br2 - lr21 * br1 + li21 * bi1;
    bi2 = bi2 - li21 * br1 - lr21 * bi1;
    double bbnd = dmax((fabs(br1) + fabs(bi1)) * (u22abs * (fabs(ur11r) + fabs(ui11r))), fabs(br2) + fabs(bi2));
    if (bbnd > 1.0 && u22abs < 1.0) { if (bbnd >= bignum * u22abs) { *scale = 1.0 / bbnd;
        br1 = *scale * br1; bi1 = *scale * bi1; br2 = *scale * br2; bi2 = *scale * bi2; } }
    double xr2, xi2;
    my_dladiv(br2, bi2, ur22, ui22, &xr2, &xi2);
    double xr1 = ur11r * br1 - ui11r * bi1 - ur12s * xr2 + ui12s * xi2;
    double xi1 = ui11r * br1 + ur11r * bi1 - ui12s * xr2 - ur12s * xi2;
    if (zswap[icmax-1]) { x(1,1) = xr2; x(2,1) = xr1; x(1,2) = xi2; x(2,2) = xi1; }
    else { x(1,1) = xr1; x(2,1) = xr2; x(1,2) = xi1; x(2,2) = xi2; }
    *xnorm = dmax(fabs(xr1) + fabs(xi1), fabs(xr2) + fabs(xi2));
    if (*xnorm > 1.0 && cmax > 1.0) { if (*xnorm > bignum / cmax) { double temp = cmax / bignum;
        x(1,1) *= temp; x(2,1) *= temp; x(1,2) *= temp; x(2,2) *= temp; *xnorm = temp * *xnorm; *scale = temp * *scale; } }
}
